class KeyUpdatePayload(BaseModel):
    label: str
    description: Optional[str] = None

@router.patch("/api/v1/api-keys/{key_id}/metadata")
def update_key_metadata(
    key_id: int,
    payload: KeyUpdatePayload,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user)
):
    key = db.query(UserApiKey).filter(
        UserApiKey.id == key_id,
        UserApiKey.user_id == current_user.id
    ).first()
    if not key:
        raise HTTPException(status_code=404, detail="API key not found")
    key.label = payload.label
    if payload.description is not None:
        key.description = payload.description
    db.commit()
    return {"id": key.id, "label": key.label, "description": key.description}
